# -*- coding: utf-8 -*-
import json

Q = []

def add(cat, q, choices, correct, exps):
    assert len(choices) == 4 and len(exps) == 4
    Q.append({
        "category": cat, "question": q, "choices": choices,
        "correct": correct, "explanations": exps
    })

