# ============================================================ POO générale (25)
add("POO","Quel est le principe qui consiste à cacher les détails internes d'un objet et à n'exposer qu'une interface publique ?",
    ["Héritage","Encapsulation","Polymorphisme","Abstraction"], 1,
    ["L'héritage permet de réutiliser du code d'une classe dans une autre, ce n'est pas la dissimulation des détails.","L'encapsulation consiste précisément à protéger les données internes et à ne les exposer que via des méthodes publiques.","Le polymorphisme concerne la capacité d'un même appel à se comporter différemment selon l'objet réel.","L'abstraction consiste à ne représenter que les aspects essentiels, un concept proche mais distinct de l'encapsulation stricte."])
add("POO","Que signifie le polymorphisme en programmation orientée objet ?",
    ["La possibilité qu'un objet appartienne à plusieurs classes non liées simultanément","La capacité d'objets de classes différentes (liées par héritage/interface) à répondre différemment à un même message","L'impossibilité de redéfinir une méthode","Le fait qu'une classe ne puisse avoir qu'une seule méthode"], 1,
    ["Un objet a un type précis ; le polymorphisme concerne le comportement selon le type réel, pas une appartenance multiple.","C'est la définition correcte : un même appel de méthode produit un comportement adapté au type réel de l'objet.","Le polymorphisme repose justement sur la redéfinition (surcharge/redéfinition) des méthodes.","Une classe peut définir autant de méthodes que nécessaire, sans lien avec le polymorphisme."])
add("POO","Qu'est-ce qu'une classe abstraite ?",
    ["Une classe qui ne peut pas être instanciée directement et sert de base à d'autres classes","Une classe sans aucun attribut","Une classe qui ne peut avoir qu'une seule sous-classe","Une classe automatiquement supprimée après compilation"], 0,
    ["C'est la définition correcte : elle définit un contrat/comportement partiel, complété par les classes filles.","Une classe abstraite peut tout à fait posséder des attributs.","Une classe abstraite peut être héritée par un nombre quelconque de sous-classes.","La notion de suppression après compilation n'existe pas pour une classe abstraite."])
add("POO","Quelle est la différence essentielle entre une interface et une classe abstraite (concept général POO) ?",
    ["Aucune, ce sont des synonymes stricts dans tous les langages","Une interface ne définit en général que des signatures de méthodes, une classe abstraite peut fournir une implémentation partielle","Une interface peut être instanciée directement","Une classe abstraite ne peut jamais contenir de méthode"], 1,
    ["Les deux notions se recoupent mais ne sont pas identiques selon les langages (Java, C++...).","C'est la distinction classique : l'interface est un contrat pur, la classe abstraite peut mélanger contrat et implémentation.","Ni une interface ni une classe abstraite ne peuvent être instanciées directement.","Une classe abstraite peut très bien contenir des méthodes concrètes en plus des méthodes abstraites."])
add("POO","Que désigne le terme « constructeur » dans une classe ?",
    ["Une méthode appelée automatiquement à la création d'un objet pour l'initialiser","Une méthode appelée à la destruction de l'objet","Une variable statique de la classe","Une méthode qui ne peut pas avoir de paramètres"], 0,
    ["C'est exact : le constructeur initialise l'état de l'objet au moment de son instanciation.","C'est le rôle du destructeur (ou finalize/dispose selon le langage), pas du constructeur.","Un constructeur est une méthode spéciale, pas une variable.","Un constructeur peut tout à fait accepter des paramètres (constructeur paramétré)."])
add("POO","Qu'est-ce que la surcharge de méthode (« overloading ») ?",
    ["Redéfinir une méthode héritée dans une sous-classe avec la même signature","Définir plusieurs méthodes de même nom mais avec des paramètres différents dans une même classe","Appeler une méthode plusieurs fois dans une boucle","Rendre une méthode privée"], 1,
    ["C'est la définition de la redéfinition (« overriding »), pas de la surcharge.","C'est exactement la surcharge : même nom, signatures (types/nombre de paramètres) différentes.","Appeler plusieurs fois une méthode n'a aucun rapport avec la surcharge.","La visibilité (private/public) est indépendante du concept de surcharge."])
add("POO","Qu'est-ce que la redéfinition de méthode (« overriding ») ?",
    ["Créer une méthode totalement nouvelle sans lien avec une classe mère","Fournir dans une sous-classe une nouvelle implémentation d'une méthode héritée, avec la même signature","Changer le type de retour d'une méthode uniquement","Supprimer une méthode héritée"], 1,
    ["La redéfinition concerne justement une méthode déjà existante dans la classe mère.","C'est la définition correcte : la sous-classe fournit son propre comportement pour une méthode héritée.","Le type de retour doit généralement rester compatible, la redéfinition porte sur l'implémentation entière.","La méthode reste disponible mais avec un comportement différent, elle n'est pas supprimée."])
add("POO","Que signifie le principe SOLID « S » (Single Responsibility Principle) ?",
    ["Une classe ne doit avoir qu'une seule raison de changer, donc une seule responsabilité","Une classe doit hériter d'une seule autre classe","Un programme ne doit avoir qu'une seule classe","Une méthode ne doit contenir qu'une seule instruction"], 0,
    ["C'est exactement la définition du principe de responsabilité unique.","Ce principe ne concerne pas l'héritage simple/multiple mais la cohérence des responsabilités d'une classe.","Un programme orienté objet comporte naturellement plusieurs classes.","Le principe porte sur la responsabilité globale de la classe, pas sur la taille des méthodes."])
add("POO","Quel principe SOLID stipule qu'une classe doit être ouverte à l'extension mais fermée à la modification ?",
    ["Liskov Substitution Principle","Open/Closed Principle","Interface Segregation Principle","Dependency Inversion Principle"], 1,
    ["Le LSP concerne la substituabilité des sous-classes à leur classe mère.","C'est la définition exacte de l'Open/Closed Principle (OCP).","L'ISP concerne la ségrégation des interfaces pour éviter des dépendances inutiles.","Le DIP concerne la dépendance vers des abstractions plutôt que des implémentations concrètes."])
add("POO","Qu'est-ce que l'héritage multiple ?",
    ["Une classe qui hérite de plusieurs classes mères à la fois","Une classe qui a plusieurs constructeurs","Une classe instanciée plusieurs fois","Une méthode appelée par plusieurs objets"], 0,
    ["C'est exactement la définition : une classe fille hérite simultanément de plusieurs classes de base.","Plusieurs constructeurs relèvent de la surcharge, pas de l'héritage multiple.","Instancier plusieurs fois une classe n'a aucun rapport avec l'héritage multiple.","Le partage d'une méthode entre objets est un usage normal de la POO, sans rapport direct."])
add("POO","Pourquoi Java n'autorise-t-il pas l'héritage multiple de classes (contrairement au C++) ?",
    ["Java ne supporte pas du tout l'héritage","Pour éviter l'ambiguïté du « problème du diamant »","Parce que Java est un langage interprété","Parce que Java n'a pas de classes abstraites"], 1,
    ["Java supporte pleinement l'héritage simple ainsi que l'implémentation multiple d'interfaces.","Java a choisi de limiter l'héritage de classes à une seule classe mère notamment pour éviter les ambiguïtés du problème du diamant, en s'appuyant sur les interfaces pour la flexibilité.","Le fait d'être compilé en bytecode puis exécuté sur la JVM n'est pas la raison de cette restriction.","Java possède bien des classes abstraites, ce n'est pas lié à cette limitation."])
add("POO","Que représente une association « composition » entre deux classes ?",
    ["Une relation faible où les objets sont totalement indépendants","Une relation forte où l'objet contenu ne peut exister sans l'objet conteneur","Une relation entre deux méthodes","Un synonyme strict d'héritage"], 1,
    ["C'est plutôt le cas d'une association simple, plus faible que la composition.","La composition exprime une dépendance de cycle de vie forte : la destruction du conteneur entraîne celle des objets composés.","La composition est une relation entre classes/objets, pas entre méthodes.","La composition est une relation « a-un » (has-a), distincte de l'héritage qui est une relation « est-un » (is-a)."])
add("POO","Quelle relation UML illustre le mieux le principe « est-un » (is-a) ?",
    ["Composition","Agrégation","Héritage","Dépendance"], 2,
    ["La composition exprime plutôt une relation « fait partie de » (part-of), pas « est-un ».","L'agrégation exprime aussi une relation « a-un », plus faible que la composition.","L'héritage exprime la spécialisation : une sous-classe « est-un » type particulier de sa classe mère.","La dépendance exprime qu'une classe utilise une autre, sans relation de type."])
add("POO","Qu'appelle-t-on une méthode « virtuelle » (concept général, notamment en C++) ?",
    ["Une méthode qui n'existe qu'en mémoire vive","Une méthode qui peut être redéfinie dans les classes dérivées et dont l'appel est résolu au runtime (liaison dynamique)","Une méthode qui ne fait rien","Une méthode statique uniquement"], 1,
    ["Toutes les méthodes résident en mémoire à l'exécution, ce n'est pas spécifique au mot « virtuelle ».","C'est la définition correcte : elle permet le polymorphisme grâce à la résolution dynamique de l'appel selon le type réel de l'objet.","Une méthode virtuelle peut avoir une implémentation complète, elle n'est pas nécessairement vide.","Une méthode statique appartient à la classe et n'est pas concernée par la liaison dynamique."])
add("POO","Quel est le rôle d'un destructeur dans une classe ?",
    ["Initialiser les attributs de l'objet","Libérer les ressources détenues par l'objet avant sa destruction","Créer une copie de l'objet","Comparer deux objets"], 1,
    ["C'est le rôle du constructeur, pas du destructeur.","Le destructeur est appelé lors de la destruction de l'objet pour libérer proprement les ressources (mémoire, fichiers...).","C'est le rôle d'un constructeur de copie, pas d'un destructeur.","La comparaison d'objets relève d'une méthode dédiée (equals, operator==...), pas du destructeur."])
add("POO","Qu'est-ce que l'attribut de visibilité « protected » permet en général ?",
    ["L'accès uniquement depuis la classe elle-même","L'accès depuis la classe elle-même et ses sous-classes","L'accès depuis n'importe quelle classe du programme","Aucun accès, même en interne"], 1,
    ["C'est la définition de « private », pas de « protected ».","C'est exact : protected ouvre l'accès à la classe et à ses descendants, contrairement à private.","C'est la définition de « public », pas de « protected ».","protected autorise un accès restreint mais réel, il n'interdit pas tout accès."])
add("POO","Qu'est-ce qu'un « design pattern » (patron de conception) ?",
    ["Un bug connu et documenté","Une solution réutilisable à un problème de conception récurrent en POO","Un langage de programmation","Un outil de compilation"], 1,
    ["Un design pattern n'est pas un défaut, c'est au contraire une bonne pratique éprouvée.","C'est la définition correcte : un modèle éprouvé pour résoudre un problème de conception qui revient souvent.","Un design pattern est un concept indépendant du langage, applicable dans plusieurs langages POO.","Un design pattern n'est pas un logiciel, c'est une solution conceptuelle."])
add("POO","Le patron de conception Singleton garantit quoi ?",
    ["Qu'une classe ne peut avoir aucune instance","Qu'une classe ne peut avoir qu'une seule instance accessible globalement","Que toutes les instances sont identiques en mémoire mais multiples","Qu'une classe hérite d'une seule autre classe"], 1,
    ["Le Singleton garantit au contraire l'existence d'exactement une instance, pas zéro.","C'est exactement l'objectif du patron Singleton : une unique instance, avec un point d'accès global.","Le Singleton assure qu'il n'existe qu'une seule instance, pas plusieurs instances identiques.","Ce point concerne l'héritage, sans rapport avec le patron Singleton."])
add("POO","Qu'est-ce que le couplage faible (« loose coupling ») entre classes ?",
    ["Une forte dépendance directe entre les classes","Une dépendance minimisée entre classes, facilitant la maintenance et les tests","L'absence totale de communication entre classes","Le fait de mettre tout le code dans une seule classe"], 1,
    ["C'est l'inverse : un couplage fort signifie une forte dépendance, ce qu'on cherche justement à réduire.","C'est la définition correcte : moins les classes dépendent les unes des autres, plus elles sont faciles à faire évoluer ou tester isolément.","Un couplage faible n'empêche pas toute communication, il la rend simplement moins rigide (souvent via des interfaces).","Tout regrouper dans une seule classe est l'opposé de la modularité recherchée par un couplage faible."])
add("POO","Qu'est-ce que la cohésion forte (« high cohesion ») d'une classe ?",
    ["Le fait qu'une classe regroupe des responsabilités très diverses et sans lien","Le fait que les éléments d'une classe soient étroitement liés autour d'une responsabilité claire","Le fait qu'une classe hérite de plusieurs interfaces","Le fait qu'une classe soit très volumineuse"], 1,
    ["Une cohésion forte est justement l'inverse : des responsabilités homogènes, pas dispersées.","C'est la bonne définition : tous les éléments de la classe concourent à un objectif cohérent et bien défini.","L'implémentation de plusieurs interfaces n'est pas, en soi, un indicateur de cohésion.","La taille d'une classe n'est pas directement corrélée à sa cohésion."])
add("POO","Que signifie « instancier » une classe ?",
    ["Créer un objet concret à partir du modèle défini par la classe","Supprimer une classe du code source","Hériter d'une classe","Transformer une classe en interface"], 0,
    ["C'est exactement le sens du terme : créer un objet (instance) selon le plan fourni par la classe.","Instancier ne supprime rien, cela crée un nouvel objet en mémoire.","Hériter est un mécanisme entre classes, différent de l'instanciation d'un objet.","Transformer une classe en interface n'est pas ce que signifie « instancier »."])
add("POO","Quel terme désigne l'ensemble des attributs et méthodes définissant le comportement partagé de tous les objets d'une classe ?",
    ["Instance","Classe","Objet","Package"], 1,
    ["Une instance est un objet particulier créé à partir de la classe, pas la définition elle-même.","C'est la classe qui définit la structure (attributs) et le comportement (méthodes) communs à tous ses objets.","Un objet est une réalisation concrète (instance) de la classe, pas la définition générale.","Un package est un mécanisme d'organisation du code, pas la définition d'un comportement partagé."])
add("POO","Pourquoi préfère-t-on souvent la composition à l'héritage dans la conception orientée objet moderne ?",
    ["Parce que l'héritage est interdit dans la plupart des langages","Parce que la composition réduit le couplage et évite la fragilité des hiérarchies d'héritage profondes","Parce que la composition est plus rapide à l'exécution dans tous les cas","Parce que l'héritage empêche toute réutilisation de code"], 1,
    ["L'héritage reste un mécanisme standard disponible dans la quasi-totalité des langages orientés objet.","C'est la raison couramment avancée (principe « favor composition over inheritance ») : plus de flexibilité et moins de dépendances rigides.","La performance dépend du contexte, ce n'est pas l'argument principal de ce principe de conception.","L'héritage permet justement la réutilisation de code, ce qui n'est pas le problème visé par ce principe."])
add("POO","Qu'est-ce qu'une méthode statique dans une classe ?",
    ["Une méthode liée à la classe elle-même, appelable sans créer d'instance","Une méthode qui ne peut jamais être appelée","Une méthode privée par défaut","Une méthode qui retourne toujours la même valeur"], 0,
    ["C'est exact : elle appartient à la classe et peut être invoquée sans instancier d'objet.","Une méthode statique est parfaitement appelable, simplement d'une manière différente (via la classe).","La visibilité (public/private) est indépendante du fait d'être statique.","Le résultat d'une méthode statique dépend de ses paramètres et de son implémentation, pas d'une constance systématique."])
add("POO","Qu'est-ce que l'abstraction en POO ?",
    ["Modéliser un concept en ne retenant que ses caractéristiques essentielles pour le contexte donné","Cacher totalement le code source d'une application","Compresser un programme pour réduire sa taille","Supprimer les commentaires du code"], 0,
    ["C'est exactement le principe d'abstraction : simplifier la réalité en ne gardant que l'essentiel pertinent.","La dissimulation du code source n'est pas ce que désigne l'abstraction en POO (cela relève plutôt de la compilation/obfuscation).","La compression n'a aucun rapport avec l'abstraction en programmation orientée objet.","La suppression de commentaires est une opération de nettoyage, sans lien avec l'abstraction."])
add("POO","Que représente un « attribut » dans une classe ?",
    ["Une fonction membre de la classe","Une donnée membre qui caractérise l'état d'un objet","Un commentaire dans le code","Le nom de la classe"], 1,
    ["Une fonction membre est appelée une méthode, pas un attribut.","C'est la bonne définition : un attribut (ou champ) stocke une information décrivant l'état de l'objet.","Un commentaire n'a aucune valeur exécutable ni représentative de l'état d'un objet.","Le nom de la classe identifie le type, ce n'est pas un attribut d'instance."])

